let libraryView,learning;
let catalog,nodes,byId,courses,videos,docs,progress,storageOK=true,activeCourse=null,activeItem=null,libraryTab='courses',libPage=1,libQuery='',libTag='Tất cả',libCourse='',playerReturn=null,noteDebounce;
const timers={running:false,left:1500,interval:null,started:0,base:0};
const dayKey=(date=new Date())=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const todayCount=()=>Object.values(progress.completed).filter(d=>dayKey(new Date(d))===dayKey()).length;
const completeCount=c=>c.videos.filter(v=>progress.completed[v.id]).length;
const pct=c=>c.videos.length?Math.round(completeCount(c)/c.videos.length*100):0;
const fileURL=f=>`https://drive.google.com/file/d/${encodeURIComponent(f.id)}/view`;
const folderURL=id=>`https://drive.google.com/drive/folders/${encodeURIComponent(id)}`;
const button=(label,attrs='',style='btn-primary',ic='')=>`<button class="btn ${style}" ${attrs}>${ic?icon(ic):''}${label}</button>`;
const layout=createLayout({icon});
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(progress));return true}catch{storageOK=false;toast('Trình duyệt chưa cho phép lưu. Hãy xuất tiến độ để giữ dữ liệu.');return false}}
function readState(ids){try{return safeProgress(JSON.parse(localStorage.getItem(KEY)||'{}'),ids)}catch{storageOK=false;return safeProgress({},ids)}}
function resourceTitle(f){return resourceLabel(f,byId.get(f.parent)?.name||'')}
function courseFor(id){return courses.find(c=>c.id===id)}
function pathFor(item){const parts=[];let p=byId.get(item.parent),depth=0;while(p&&p.parent!==ROOT&&depth++<15){parts.unshift(cleanTitle(p.name));p=byId.get(p.parent)}return parts.join(' / ')}
function renderNav(){const routes=[['home','Dashboard','home'],['vocabulary','Từ vựng','note'],['learn','Ngữ pháp & bài học','book'],['library','Thư viện khóa học','book'],['plan','Lộ trình của tôi','route'],['practice','Luyện tập & ôn sai','target'],['saved','Bài học đã lưu','bookmark'],['notes','Sổ ghi chú','note'],['progress','Tiến độ học tập','chart'],['content','Nguồn & phạm vi','folder'],['account','Tài khoản & lịch sử','profile']];const current=(location.hash.slice(1).split('?')[0]||'home');$('#nav').innerHTML=routes.map(([id,label,ic])=>`<a href="#${id}" aria-label="${label}" title="${label}" data-nav-label="${label}" class="nav-item ${current===id||(['course','study'].includes(current)&&id==='library')||(['quiz','cards'].includes(current)&&id==='practice')?'active':''}" ${current===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='saved'&&progress.saved.length?`<span class="nav-count">${progress.saved.length}</span>`:''}</a>`).join('');$('#page-label').textContent=routes.find(r=>r[0]===current)?.[1]||({focus:'Góc tập trung',learn:'Học chủ động',study:'Góc học theo bài',quiz:'Bài luyện tập',cards:'Thẻ từ',source:'Nguồn học liệu',course:'Chi tiết khóa học'}[current]||'Tổng quan')}
const featured=()=>['1EcEHLSxxlsRFtJCXMGimzy2rKd2Ej-zD','1m8UUnkpyTOffREm7GjITTPrDkZ5OmHUb','1L3owxwaCrNtU7tNfclhZ7ZIeM3yeq3kM'].map(courseFor).filter(Boolean);
function art(c,i=0){let word='Learn.<br>Grow.',small='YOUR NEXT CHAPTER',ic='book';const t=normalize(c.name);if(/nghe|listening/.test(t)&&!/doc|reading/.test(t)){word='Listen.<br>Learn.';small='LISTENING';ic='headphones'}else if(/reading|doc/.test(t)){word='Read.<br>Grow.';small='READING'}else if(/ngu phap|mat goc|can ban|nen tang/.test(t)){word='Back to<br>basics.';small='NỀN TẢNG';ic='spark'}else if(/study4/.test(t)){word='Step by<br>step.';small='7 PARTS · 1 GOAL';ic='headphones'}else if(/speaking|writing/.test(t)||/nói|viết/i.test(c.name)){word='Say it.<br>Write it.';small='SPEAKING & WRITING';ic='note'}else if(/prep/.test(t)){word='Aim<br>higher.';small='TOEIC JOURNEY';ic='target'}return `<div class="course-art tone-${i%5}"><span class="art-number">${String(i+1).padStart(2,'0')}</span><div class="art-word"><small>${small}</small>${word}</div><span class="art-symbol">${icon(ic)}</span></div>`}
function courseCard(c,i){return `<button class="course-card" data-course="${c.id}">${art(c,i)}<div class="course-card-content"><span class="course-category">${esc(c.tags.slice(0,2).join(' · ')||'KHÓA HỌC TOEIC')}</span><h3>${esc(c.title)}</h3><div class="course-meta"><span>${icon('video')}${fmt(c.videos.length)} video</span><span>${icon('note')}${fmt(c.docs.length)} tài liệu</span></div><div class="course-bottom"><span>${completeCount(c)?`${fmt(completeCount(c))} bài đã hoàn thành`:'Bắt đầu hành trình mới'}</span><span>${completeCount(c)?pct(c)+'%':'Khám phá ↗'}</span></div></div></button>`}
function heading(title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">LEARN AT YOUR OWN PACE</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`}
function stats(){return `<div class="stat-grid"><div class="stat"><div class="stat-icon">${icon('check')}</div><div><strong>${fmt(Object.keys(progress.completed).length)}<span class="stat-unit">bài học</span></strong><small>Đã hoàn thành</small></div></div><div class="stat"><div class="stat-icon">${icon('book')}</div><div><strong>${fmt(courses.length)}<span class="stat-unit">khóa học</span></strong><small>Trong thư viện của bạn</small></div></div><div class="stat"><div class="stat-icon">${icon('clock')}</div><div><strong>${fmt(Math.floor(progress.focus/60))}<span class="stat-unit">phút</span></strong><small>Thời gian tập trung đã lưu</small></div></div></div>`}
function firstVideo(){const last=byId.get(progress.last);return last&&isVideo(last)?last:featured().flatMap(c=>c.videos).find(v=>!progress.completed[v.id])||videos[0]}
function home(){const v=firstVideo(),date=new Date().toLocaleDateString('vi-VN',{weekday:'long',day:'numeric',month:'long'}),daily=Math.min(100,Math.round(todayCount()/progress.daily*100));return `${heading('Chào bạn, cùng học nhé <span style="font-size:23px">☀</span>','Thêm một ngày mới, thêm một bước gần hơn đến mục tiêu.',`<span class="date-badge">${icon('calendar')}${esc(date)}</span>`)}<div class="dashboard-top"><section class="hero"><div class="hero-content"><div class="eyebrow">MỘT CHÚT KIÊN TRÌ, MỘT CHẶNG ĐƯỜNG XA</div><h2>Mỗi ngày một chút,<br><em>gần hơn mục tiêu.</em></h2><p>Kho bài giảng đã sẵn sàng. Chọn một bài học,<br>và dành khoảng thời gian này cho chính bạn.</p>${button(progress.last?'Tiếp tục học':'Bắt đầu học ngay',v?`data-play="${v.id}"`:'data-nav="library"','btn-primary','play')}</div><div class="hero-art" aria-hidden="true"><div class="hero-circle"></div><span class="art-star">✦</span><span class="art-star small">✧</span><div class="book"></div><div class="art-tag"><span>✓</span> You can do this!</div></div></section><section class="goal-card"><div class="card-label">Mục tiêu của tôi ${icon('target')}</div><div class="goal-score">${progress.goal}<span>điểm TOEIC</span></div><div class="goal-caption">Từng bước chinh phục phiên bản tốt hơn.</div><div class="progress-track"><span style="width:${daily}%"></span></div><div class="progress-caption"><span>Nhịp học hôm nay</span><strong>${todayCount()}/${progress.daily} bài</strong></div><button class="text-button" data-settings>Điều chỉnh mục tiêu ${icon('chevron')}</button></section></div>${stats()}${progress.last&&v?`<div class="continue-strip"><span class="round-play">${icon('play')}</span><div><small>BÀI HỌC GẦN NHẤT</small><h3>${esc(resourceTitle(v))}</h3></div>${button('Học tiếp',`data-play="${v.id}"`,'btn-soft','arrow')}</div>`:''}${libraryView.homeGroups()}<div class="continue-strip"><span class="round-play">${icon('target')}</span><div><h3>Học xong, tự kiểm tra ngay</h3><small>${learning?.questionCount||0} câu hỏi từ tài liệu đã đọc · giải thích · ôn câu sai</small></div><a href="#practice" class="btn btn-primary">${icon('arrow')}Luyện tập</a></div><div class="home-grid"><section><div class="section-title"><div><h2>Khám phá hành trình của bạn</h2><p>Những khóa học từ thư viện Google Drive.</p></div><a class="text-button" href="#library">Xem tất cả ${icon('arrow')}</a></div><div class="course-grid">${featured().map(courseCard).join('')}</div></section><aside class="daily-side"><div class="section-title"><h2>Một chút mỗi ngày</h2></div><div class="daily-card"><h3>Hôm nay, mình sẽ…</h3><p>Duy trì nhịp học, bắt đầu từ việc nhỏ.</p><div class="daily-number"><span>Mục tiêu bài học</span><strong>${todayCount()} / ${progress.daily}</strong></div><div class="progress-track"><span style="width:${daily}%"></span></div>${task('Hoàn thành '+progress.daily+' bài học','Một bước tiến mới',todayCount()>=progress.daily)}${task('Ghi lại điều vừa học','Để kiến thức ở lại lâu hơn',Object.values(progress.notes).some(n=>n.trim()))}${task('Dành 25 phút tập trung','Một khoảng thời gian cho bạn',progress.focus>=1500)}</div><div class="study-tip">${icon('spark')}<span>Không cần học thật nhiều một lúc.<br>Chỉ cần trở lại, mỗi ngày.</span></div></aside></div><div class="timer-card"><div><h3>Góc tập trung · 25 phút</h3><p>Bấm bắt đầu khi bạn sẵn sàng. Thời gian lưu trên trình duyệt này.</p></div><span class="timer-value" data-timer-value>25:00</span>${button('Bắt đầu','data-timer','btn-soft','play')}</div>`}
function task(title,sub,done){return `<div class="task"><span class="task-check ${done?'done':''}">${done?icon('check'):''}</span><div>${esc(title)}<small>${sub}</small></div></div>`}
function libraryOriginal(){return `${heading('Thư viện của bạn','Một nơi cho tất cả bài giảng. Chọn điều bạn muốn học hôm nay.')}<section class="library"><div class="tabs" role="tablist" aria-label="Loại học liệu">${[['courses','Khóa học',courses.length],['videos','Video bài giảng',videos.length],['docs','Tài liệu',docs.length]].map(([k,label,count])=>`<button class="tab ${libraryTab===k?'active':''}" data-tab="${k}" role="tab" aria-selected="${libraryTab===k}">${label} <span class="muted">(${fmt(count)})</span></button>`).join('')}</div><div class="filters"><label class="search-box">${icon('search')}<input id="library-search" type="search" placeholder="Tìm theo tên bài, ngữ pháp, Part 1…" value="${esc(libQuery)}" aria-label="Tìm kiếm học liệu"></label><select id="course-filter" aria-label="Lọc khóa học" ${libraryTab==='courses'?'hidden':''}><option value="">Tất cả khóa học</option>${courses.map(c=>`<option value="${c.id}" ${libCourse===c.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></div><div class="filter-chips" aria-label="Lọc chủ đề">${['Tất cả','Nền tảng','Listening','Reading','Ngữ pháp','Từ vựng','Speaking & Writing','Luyện đề'].map(t=>`<button class="chip ${libTag===t?'active':''}" data-tag="${esc(t)}" aria-pressed="${libTag===t}">${esc(t)}</button>`).join('')}</div><div id="library-results" aria-live="polite"></div></section>`}
function library(){
  const html=libraryOriginal(),group=new URLSearchParams(location.hash.split('?')[1]||'').get('group');
  return libraryTab==='courses'?html.replace('<div class="filters">',libraryView.libraryIntro(group)+'<div class="filters">').replace('<div class="filter-chips"','<div hidden class="filter-chips"'):html;
}
function fillLibrary(){const source=libraryTab==='courses'?courses:libraryTab==='videos'?videos:docs,q=normalize(libQuery.trim());const list=source.filter(f=>(!q||f.search.includes(q))&&(libTag==='Tất cả'||f.tags.includes(libTag))&&(!libCourse||libraryTab==='courses'||f.course===libCourse));if(libraryTab==='courses'){$('#library-results').innerHTML=libraryView.groupedCourses(list);return;}const size=libraryTab==='courses'?12:25,max=Math.max(1,Math.ceil(list.length/size));libPage=Math.min(libPage,max);$('#library-results').innerHTML=`<p class="result-summary">${fmt(list.length)} ${libraryTab==='courses'?'khóa học':libraryTab==='videos'?'video':'tài liệu'}${q?' phù hợp với tìm kiếm':''}</p>${list.length?(libraryTab==='courses'?`<div class="course-grid">${list.slice((libPage-1)*size,libPage*size).map((c,i)=>courseCard(c,c.index)).join('')}</div>`:`<div class="video-list">${list.slice((libPage-1)*size,libPage*size).map(videoRow).join('')}</div>`):empty('Chưa tìm thấy bài phù hợp','Thử từ khóa ngắn hơn hoặc chọn “Tất cả” để mở rộng tìm kiếm.','search')}${max>1?`<div class="pagination">${button('Trang trước',`data-page="${libPage-1}" ${libPage===1?'disabled':''}`,'btn-secondary','back')}<span>${libPage} / ${max}</span>${button('Trang sau',`data-page="${libPage+1}" ${libPage===max?'disabled':''}`,'btn-secondary','arrow')}</div>`:''}`}
function empty(title,desc,ic='book',action=''){return `<div class="empty">${icon(ic)}<h3>${title}</h3><p>${desc}</p>${action}</div>`}
function videoRow(f){const video=isVideo(f),done=Boolean(progress.completed[f.id]),c=courseFor(f.course);return `<div class="video-row"><button class="row-icon" data-play="${f.id}" aria-label="${video?'Xem video':'Mở tài liệu'} ${esc(resourceTitle(f))}">${icon(video?'play':f.mime.startsWith('audio/')?'headphones':'note')}</button><button class="video-info" data-play="${f.id}" style="text-align:left"><h3>${esc(resourceTitle(f))}</h3><p>${esc(c?.title||'Học liệu')} ${f.path?'· '+esc(f.path):''}</p></button>${learning?`<a class="icon-button" href="${learning.studyURL(f.course,f.parent,f.id)}" data-learn-open aria-label="Mở góc học theo bài">${icon('target')}</a>`:''}${done?`<span class="row-check">${icon('check')} Đã học</span>`:''}${video?`<button class="icon-button ${progress.saved.includes(f.id)?'saved':''}" data-save="${f.id}" aria-label="${progress.saved.includes(f.id)?'Bỏ lưu':'Lưu'} bài học" aria-pressed="${progress.saved.includes(f.id)}">${icon('bookmark')}</button>`:`<a class="icon-button" href="${fileURL(f)}" target="_blank" rel="noopener noreferrer" aria-label="Mở trên Google Drive">${icon('external')}</a>`}</div>`}
function courseDetail(id,folder){activeCourse=courseFor(id);return libraryView.courseDetail(id,folder)}
function plan(){const find=(term,max=3)=>courses.filter(c=>normalize(c.name).match(term)).slice(0,max);const stages=[{title:'Xây nền vững, học nhẹ nhàng',text:'Bắt đầu với cấu trúc câu, từ loại và các thì. Mỗi bài giảng, ghi lại một ví dụ của riêng mình.',cs:find(/mat goc|ngu phap|can ban|nen tang/)},{title:'Tạo nhịp nghe và đọc mỗi ngày',text:'Luân phiên một buổi nghe, một buổi đọc. Nghe lại đoạn khó và đọc kỹ lời giải trước khi sang bài mới.',cs:find(/study4|prep|30 days/)},{title:'Luyện đề, nhìn lại và cải thiện',text:'Học các bài giải đề, ghi chú lỗi lặp lại và quay về ôn chủ đề còn yếu. Giữ nhịp học phù hợp với thời gian của bạn.',cs:find(/cap toc|benzen|ms thanh/)}];return `${heading('Một lộ trình, nhịp độ của bạn','Gợi ý học tập dựa trên các nhóm khóa học trong thư viện.')}<div class="plan-overview"><div><h3>Mục tiêu ${progress.goal} điểm · ${progress.daily} bài mỗi ngày</h3><p>Lộ trình tham khảo, bạn có thể bắt đầu ở bất kỳ chặng nào.</p></div>${button('Điều chỉnh','data-settings','btn-secondary','target')}</div>${stages.map((s,i)=>`<section class="plan-stage"><span class="stage-number">0${i+1}</span><div class="stage-content"><div class="eyebrow">CHẶNG ${i+1}</div><h2>${s.title}</h2><p>${s.text}</p><div class="stage-courses">${s.cs.map(c=>`<button class="stage-course" data-course="${c.id}">${esc(c.title)} ↗</button>`).join('')}</div></div></section>`).join('')}<p class="fine-print">Lộ trình do TOEIC Studio đề xuất theo tên và nhóm tài liệu. Mục tiêu điểm giúp bạn định hướng, không phải dự đoán kết quả thi.</p>`}
function saved(){const list=progress.saved.map(id=>byId.get(id)).filter(Boolean);return `${heading('Để dành cho buổi học sau','Những bài giảng bạn muốn xem lại, ở ngay đây.')}<div class="video-list">${list.length?list.map(videoRow).join(''):empty('Một góc nhỏ cho bài học yêu thích','Bấm biểu tượng đánh dấu bên cạnh video để lưu lại.','bookmark',button('Khám phá thư viện','data-nav="library"','btn-primary','book'))}</div>`}
function notes(){const list=Object.entries(progress.notes).filter(([id,note])=>note.trim()&&byId.has(id));return `${heading('Những điều mình đã học','Ghi lại để nhớ lâu hơn. Ghi chú tự lưu trên trình duyệt này.')}<p class="result-summary">${fmt(list.length)} ghi chú</p>${list.length?list.map(([id,note])=>{const f=byId.get(id);return `<article class="note-card"><h3>${esc(resourceTitle(f))}</h3><pre>${esc(note)}</pre><div class="note-footer"><span>${esc(courseFor(f.course)?.title||'')}</span><button class="text-button" data-play="${id}">Mở bài học ${icon('arrow')}</button></div></article>`}).join(''):empty('Cuốn sổ của bạn đang chờ dòng đầu tiên','Mở một video và viết vào ô ghi chú bên dưới để bắt đầu.','note',button('Chọn bài học','data-nav="library"','btn-primary','book'))}`}
function progressView(){const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {key:dayKey(d),label:d.toLocaleDateString('vi-VN',{weekday:'short'}),count:0}});for(const date of Object.values(progress.completed)){const d=days.find(d=>d.key===dayKey(new Date(date)));if(d)d.count++}const max=Math.max(1,...days.map(d=>d.count));const active=courses.filter(c=>completeCount(c)>0||c.videos.some(v=>v.id===progress.last));return `${heading('Nhìn lại những bước tiến','Mỗi bài học hoàn thành đều là một điều đáng ghi nhận.',button('Mục tiêu','data-settings','btn-secondary','target'))}${stats()}<div class="progress-layout"><section class="panel"><div class="section-title"><h2>Nhịp học 7 ngày qua</h2><span class="focus-pill">${days.reduce((n,d)=>n+d.count,0)} bài</span></div><p class="fine-print">Số bài bạn đánh dấu hoàn thành, theo ngày trên thiết bị.</p><div class="week-chart">${days.map((d,i)=>`<div class="week-day"><div class="week-bar ${i===6?'today':''}" style="height:${Math.max(3,105*d.count/max)}px"><span>${d.count}</span></div><span>${esc(d.label)}</span></div>`).join('')}</div></section><section class="panel"><h2>Hành trình đang học</h2>${active.length?active.map(c=>`<div class="progress-course"><div><button data-course="${c.id}">${esc(c.title)}</button><small>${completeCount(c)}/${fmt(c.videos.length)}</small></div><div class="progress-track"><span style="width:${pct(c)}%"></span></div></div>`).join(''):`<p class="fine-print" style="margin-top:20px">Bắt đầu một khóa học để thấy tiến độ của bạn tại đây.</p>${button('Chọn khóa học','data-nav="library"','btn-soft','book')}`}</section></div><div class="panel section-gap"><h3>Dữ liệu học tập của bạn</h3><p class="fine-print">Tiến độ, ghi chú và bài đã lưu được giữ trên trình duyệt này, chưa đồng bộ giữa các thiết bị. Xuất một bản sao để lưu trữ hoặc chuyển sang máy khác.</p><div class="data-actions">${button('Xuất tiến độ','data-export','btn-secondary','download')}<label class="btn btn-secondary file-control" tabindex="0">${icon('folder')}Nhập tiến độ<input type="file" id="import-progress" accept="application/json,.json" aria-label="Nhập tệp tiến độ JSON"></label></div>${!storageOK?'<p class="error-message">Trình duyệt chưa cho phép lưu dữ liệu. Hãy xuất tiến độ trước khi đóng trang.</p>':''}</div>`}
function source(){return `${heading('Từ thư viện của bạn','Học liệu gốc trên Google Drive, trong một không gian học tập riêng.')}<div class="source-banner">${driveIcon}<div><h3>Thư mục TOEIC đã được lập danh mục</h3><p>Nhập ngày ${esc(catalog.importedDate)} · Video và tài liệu vẫn nằm trên Google Drive.</p></div></div><div class="source-grid"><section class="panel"><h3>Combo khóa luyện thi TOEIC</h3><p>Danh mục được đọc từ thư mục bạn cung cấp, giữ liên kết đến từng bài giảng và tài liệu gốc.</p><div class="source-summary"><div class="source-number">${fmt(courses.length)}<small>nhóm khóa học</small></div><div class="source-number">${fmt(videos.length)}<small>video bài giảng</small></div><div class="source-number">${fmt(docs.length)}<small>tài liệu & âm thanh</small></div></div><a class="btn btn-primary" href="${ROOT_URL}" target="_blank" rel="noopener noreferrer">${icon('external')}Mở Google Drive gốc</a></section><section class="panel"><h3>Cách mở video và cập nhật thư viện</h3><p>Video được phát bằng trình xem Google Drive. Hãy đăng nhập tài khoản Google có quyền truy cập thư mục. Nếu video không hiển thị, bấm “Mở trên Drive” trong cửa sổ bài học.</p><p>Đây là danh mục đã nhập, chưa tự động đồng bộ thay đổi từ Drive. Khi bạn thêm bài mới, yêu cầu cập nhật thư viện trong chat để đọc lại danh mục.</p><p>Tiến độ do bạn đánh dấu thủ công. Web không đọc được vị trí xem trong trình phát của Google.</p></section></div>${catalog.incompleteFolders?`<p class="fine-print section-gap">${fmt(catalog.incompleteFolders)} thư mục chưa đọc hết hoặc chưa đọc được. Bạn vẫn có thể mở thư mục gốc để xem toàn bộ.</p>`:''}<p class="fine-print section-gap">Tên và cách nhóm bài học dựa trên danh mục nguồn; nội dung video chưa được phiên âm hay xác minh. Các tệp giới thiệu nhóm và quảng bá không được đưa vào danh sách học liệu.</p>`}
function navigate(){if(!catalog)return;const [route,query]=location.hash.slice(1).split('?'),params=new URLSearchParams(query||'');activeCourse=null;renderNav();layout.closeMobile();let html;switch(route){case'library':if(params.has('tab'))libraryTab=['courses','videos','docs'].includes(params.get('tab'))?params.get('tab'):'courses';html=library();break;case'course':html=courseDetail(params.get('id'),params.get('folder'));break;case'plan':html=plan();break;case'saved':html=saved();break;case'notes':html=notes();break;case'progress':html=progressView();break;case'source':html=source();break;case'practice':html=learning.hub(params);break;case'focus':html=heading('Góc tập trung · 25 phút','Bấm bắt đầu khi sẵn sàng. Chỉ thời gian bộ đếm đang chạy được lưu.')+`<div class="timer-card"><div><h3>Một khoảng thời gian dành cho việc học</h3><p>Có thể chuyển sang bài học trong khi bộ đếm chạy.</p></div><span class="timer-value" data-timer-value>25:00</span>${button('Bắt đầu','data-timer','btn-soft','play')}</div>`;break;case'vocabulary':html=learning.vocabulary();break;case'content':html=learning.sourceAudit();break;case'account':html=learning.accountPage(params);break;case'learn':html=learning.activePage(params);break;case'quiz':html=learning.quiz(params);break;case'cards':html=learning.cards(params);break;case'study':html=learning.studyPage(params);break;default:html=learning.dashboard()}$('#main').innerHTML=html;if(route==='library')fillLibrary();if(route==='course')libraryView.fillFolder();learning?.afterRender();layout.sync();updateTimerUI();window.scrollTo({top:0,behavior:'instant'});document.title=`${$('#page-label').textContent} · TOEIC Studio`}
function refresh(){const scroll=window.scrollY;navigate();window.scrollTo({top:scroll,behavior:'instant'})}
function flushNote(){clearTimeout(noteDebounce);if(activeItem&&$('#note-editor')){progress.notes[activeItem.id]=$('#note-editor').value;persist()}}
function openPlayer(id){const f=byId.get(id);if(!f||isFolder(f))return;flushNote();playerReturn=document.activeElement;activeItem=f;const c=courseFor(f.course),video=isVideo(f);progress.last=video?id:progress.last;persist();const scope=libraryView.index.folders.get(f.parent);const list=video?scope.videos:scope.docs,index=list.findIndex(v=>v.id===id),done=Boolean(progress.completed[id]);const iframeURL=`https://drive.google.com/file/d/${encodeURIComponent(id)}/preview`;$('#player').innerHTML=`<div class="player-header"><div><small>${esc(c.title)} · ${esc(cleanTitle(byId.get(f.parent)?.name||''))}</small><h2 id="player-title">${esc(resourceTitle(f))}</h2></div><button class="icon-button" data-close-player aria-label="Đóng bài học">${icon('close')}</button></div><div class="player-layout"><div class="player-main"><div class="video-frame"><iframe src="${iframeURL}" title="${esc(resourceTitle(f))}" allow="autoplay; fullscreen; encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div><div class="drive-help"><span>Cần tài khoản Google có quyền xem. Nếu khung phát trống, mở trên Drive.</span><a href="${fileURL(f)}" target="_blank" rel="noopener noreferrer">Mở trên Drive ↗</a></div><div class="player-toolbar"><a class="btn btn-soft" href="${learning.studyURL(f.course,f.parent,f.id)}" data-learn-open>${icon('target')}Học & luyện tập</a>${video?button(done?'Đã hoàn thành':'Đánh dấu hoàn thành',`data-complete="${id}" aria-pressed="${done}"`,done?'btn-soft':'btn-primary','check'):''}${video?button(progress.saved.includes(id)?'Đã lưu':'Lưu bài',`data-save="${id}" aria-pressed="${progress.saved.includes(id)}"`,'btn-secondary','bookmark'):''}<div class="next-prev">${button('Trước',`data-play="${list[index-1]?.id||''}" ${index<1?'disabled':''}`,'btn-secondary','back')}${button('Bài tiếp',`data-play="${list[index+1]?.id||''}" ${index>=list.length-1?'disabled':''}`,'btn-secondary','arrow')}</div></div><label class="note-label" for="note-editor">Ghi chú của mình <small id="note-status">${storageOK?'Tự lưu trên trình duyệt':'Chưa được lưu trên thiết bị'}</small></label><textarea class="note-editor" id="note-editor" maxlength="20000" placeholder="Điều mình vừa học, ví dụ hay, câu hỏi cần xem lại…">${esc(progress.notes[id]||'')}</textarea></div><aside class="player-aside"><h3>${video?'Bài giảng trong chủ đề':'Tài liệu trong chủ đề'}</h3><p>${index+1} / ${fmt(list.length)} · ${video?fmt(scope.videos.filter(v=>progress.completed[v.id]).length)+' video trong chủ đề đã học':'Google Drive'}</p><a class="text-button player-chapter" data-player-chapter href="${libraryView.url(c.id,f.parent)}">${icon('folder')} Xem chương & tài liệu</a><div class="playlist">${list.map((v,i)=>`<button data-play="${v.id}" class="${v.id===id?'active':''}" ${v.id===id?'aria-current="true"':''}><span>${String(i+1).padStart(2,'0')}</span><span>${esc(resourceTitle(v))}</span>${progress.completed[v.id]?icon('check'):''}</button>`).join('')}</div></aside></div>`;if(!$('#player').open)$('#player').showModal();$('#player .playlist .active')?.scrollIntoView({block:'nearest'});$('#player').scrollTop=0}
function closePlayer(){flushNote();$('#player').close();$('#player').innerHTML='';activeItem=null;refresh();playerReturn?.focus?.()}
function toggleSaved(id){if(!byId.has(id))return;progress.saved=progress.saved.includes(id)?progress.saved.filter(x=>x!==id):[...progress.saved,id];persist();renderNav();const yes=progress.saved.includes(id);document.querySelectorAll(`[data-save="${id}"]`).forEach(b=>{b.classList.toggle('saved',yes);b.setAttribute('aria-pressed',String(yes));b.setAttribute('aria-label',yes?'Bỏ lưu bài học':'Lưu bài học');if(b.classList.contains('btn'))b.innerHTML=icon('bookmark')+(yes?'Đã lưu':'Lưu bài')});if(!$('#player').open)refresh();toast(yes?'Đã lưu bài học cho buổi sau.':'Đã bỏ bài học khỏi mục đã lưu.')}
function toggleCompleted(id){if(!isVideo(byId.get(id)||{mime:''}))return;const yes=!progress.completed[id];if(yes)progress.completed[id]=new Date().toISOString();else delete progress.completed[id];persist();if(activeItem?.id===id)openPlayer(id);else refresh();toast(yes?'Thêm một bài học hoàn thành. Tiếp tục nhé!':'Đã bỏ đánh dấu hoàn thành.')}
function settings(){const d=$('#settings');d.innerHTML=`<form id="goal-form"><div class="dialog-header"><h2 id="settings-title">Mục tiêu của bạn</h2><button type="button" class="icon-button" data-close-settings aria-label="Đóng">${icon('close')}</button></div><p class="fine-print">Chọn một mục tiêu vừa sức và trở lại học đều đặn.</p><label class="form-field">Mục tiêu TOEIC<select name="goal">${[450,650,850].map(n=>`<option ${n===progress.goal?'selected':''} value="${n}">${n} điểm</option>`).join('')}</select></label><label class="form-field">Nhịp học mỗi ngày<select name="daily">${[1,2,3,5].map(n=>`<option ${n===progress.daily?'selected':''} value="${n}">${n} bài học / ngày</option>`).join('')}</select></label><p class="fine-print">Bạn luôn có thể thay đổi khi thời gian và nhu cầu thay đổi.</p><button class="btn btn-primary" type="submit">${icon('check')}Lưu mục tiêu</button></form>`;d.showModal()}
function updateTimerUI(){const t=`${String(Math.floor(timers.left/60)).padStart(2,'0')}:${String(timers.left%60).padStart(2,'0')}`;document.querySelectorAll('[data-timer-value]').forEach(e=>e.textContent=t);document.querySelectorAll('[data-timer]').forEach(e=>e.innerHTML=icon(timers.running?'pause':'play')+(timers.running?'Tạm dừng':timers.left===1500?'Bắt đầu':'Tiếp tục'))}
function bankFocus(){if(!timers.running)return;const elapsed=Math.min(timers.base,Math.max(0,Math.floor((Date.now()-timers.started)/1000)));progress.focus+=elapsed;timers.left=Math.max(0,timers.base-elapsed);timers.running=false;clearInterval(timers.interval);persist()}
function toggleTimer(){if(timers.running){bankFocus();refresh();return}if(timers.left<=0)timers.left=1500;timers.running=true;timers.started=Date.now();timers.base=timers.left;timers.interval=setInterval(()=>{timers.left=Math.max(0,timers.base-Math.floor((Date.now()-timers.started)/1000));updateTimerUI();if(timers.left===0){bankFocus();toast('Bạn đã dành 25 phút tập trung. Nghỉ một chút nhé!');timers.left=1500;refresh()}},500);updateTimerUI()}
function exportProgress(){flushNote();const blob=new Blob([JSON.stringify({app:'TOEIC Studio',exportedAt:new Date().toISOString(),...progress,learning:learning?.exportData()},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`toeic-studio-tien-do-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Đã xuất bản sao tiến độ và ghi chú.')}
async function importProgress(file){if(!file)return;if(file.size>5000000){toast('Tệp quá lớn. Vui lòng chọn bản xuất dưới 5 MB.');return}try{const v=JSON.parse(await file.text());if(v.app!=='TOEIC Studio'||v.version!==1||!v.completed||!Array.isArray(v.saved)||!v.notes)throw Error();if(!confirm('Thay tiến độ, mục tiêu và ghi chú hiện tại bằng bản nhập này? Hãy xuất bản sao trước nếu cần.'))return;bankFocus();progress=safeProgress(v,new Set(nodes.map(n=>n.id)));if(v.learning)learning.importData(v.learning);persist();refresh();toast('Đã nhập dữ liệu học tập.')}catch{toast('Không đọc được tệp. Hãy chọn tệp JSON đã xuất từ TOEIC Studio.')}}

document.addEventListener('click',event=>{const b=event.target.closest('button,a');if(!b)return;if(b.hasAttribute('data-player-chapter')){closePlayer();}else if(b.hasAttribute('data-nav'))location.hash=b.dataset.nav;else if(b.hasAttribute('data-course'))location.hash='course?id='+b.dataset.course;else if(b.hasAttribute('data-play'))openPlayer(b.dataset.play);else if(b.hasAttribute('data-save'))toggleSaved(b.dataset.save);else if(b.hasAttribute('data-complete'))toggleCompleted(b.dataset.complete);else if(b.hasAttribute('data-close-player'))closePlayer();else if(b.hasAttribute('data-settings'))settings();else if(b.hasAttribute('data-close-settings'))$('#settings').close();else if(b.hasAttribute('data-tab')){libraryTab=b.dataset.tab;libPage=1;if(libraryTab==='courses')libTag='Tất cả';history.replaceState(null,'','#library');refresh()}else if(b.hasAttribute('data-tag')){libTag=b.dataset.tag;libPage=1;document.querySelectorAll('[data-tag]').forEach(x=>{x.classList.toggle('active',x.dataset.tag===libTag);x.setAttribute('aria-pressed',String(x.dataset.tag===libTag))});fillLibrary()}else if(b.hasAttribute('data-page')){libPage=Number(b.dataset.page);fillLibrary();$('#library-results').scrollIntoView({block:'start',behavior:'instant'})}else if(b.hasAttribute('data-timer'))toggleTimer();else if(b.hasAttribute('data-export'))exportProgress();else if(b.hasAttribute('data-docs-course')){libCourse=b.dataset.docsCourse;libraryTab='docs';libPage=1;location.hash='library'}});
document.addEventListener('input',event=>{if(event.target.id==='library-search'){libQuery=event.target.value;libPage=1;fillLibrary()}else if(event.target.id==='note-editor'){clearTimeout(noteDebounce);$('#note-status').textContent='Đang lưu…';noteDebounce=setTimeout(()=>{if(persistNote())$('#note-status').textContent='Đã lưu trên trình duyệt';else $('#note-status').textContent='Chưa lưu được · hãy sao chép ghi chú'},450)}});
function persistNote(){if(!activeItem||!$('#note-editor'))return false;progress.notes[activeItem.id]=$('#note-editor').value;return persist()}
document.addEventListener('change',event=>{if(event.target.id==='course-filter'){libCourse=event.target.value;libPage=1;fillLibrary()}if(event.target.id==='import-progress')importProgress(event.target.files[0])});
document.addEventListener('submit',event=>{if(event.target.id!=='goal-form')return;event.preventDefault();const form=new FormData(event.target);progress.goal=Number(form.get('goal'));progress.daily=Number(form.get('daily'));persist();$('#settings').close();refresh();toast('Đã lưu mục tiêu. Mình bắt đầu từ hôm nay nhé.')});
$('#search-icon').innerHTML=icon('search');$('#drive-icon').innerHTML=driveIcon;

function globalSearch(){libraryTab='videos';libTag='Tất cả';libCourse='';libPage=1;if(location.hash==='#library'){refresh();$('#library-search')?.focus()}else{location.hash='library';setTimeout(()=>$('#library-search')?.focus(),30)}}
$('#search-shortcut').onclick=globalSearch;
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)&&!$('#player').open&&!$('#settings').open){e.preventDefault();globalSearch()}});
$('#player').addEventListener('cancel',e=>{e.preventDefault();closePlayer()});$('#player').addEventListener('click',e=>{if(e.target===$('#player')){const r=$('#player').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePlayer()}});
window.addEventListener('hashchange',navigate);
window.addEventListener('pagehide',()=>{flushNote();bankFocus()});
window.addEventListener('storage',e=>{if(e.key===KEY&&!$('#player').open){progress=readState(new Set(nodes.map(n=>n.id)));refresh()}});
async function boot(){try{const response=await fetch('./catalog.json');if(!response.ok)throw Error('Không tải được danh mục');catalog=await response.json();nodes=catalog.items;byId=new Map(nodes.map(n=>[n.id,n]));courses=nodes.filter(n=>n.parent===ROOT&&isFolder(n)).sort((a,b)=>a.name.localeCompare(b.name,'vi',{numeric:true}));const usable=nodes.filter(n=>isFolder(n)||isLearningResource(n));videos=usable.filter(isVideo);docs=usable.filter(isDocument);for(const f of [...videos,...docs]){f.path=pathFor(f);f.tags=tagsFor(f.name+' '+f.path+' '+(byId.get(f.course)?.name||''));f.search=normalize(resourceTitle(f)+' '+f.path+' '+(names[f.course]||byId.get(f.course)?.name||''))}for(const [i,c]of courses.entries()){c.title=names[c.id]||cleanTitle(c.name);c.videos=videos.filter(f=>f.course===c.id).sort((a,b)=>(a.path+'/'+a.name).localeCompare(b.path+'/'+b.name,'vi',{numeric:true}));c.docs=docs.filter(f=>f.course===c.id);c.tags=[...new Set([...tagsFor(c.name),...c.videos.flatMap(v=>v.tags)])];c.search=normalize(c.name+' '+c.title);c.index=i}libraryView=createLibraryView({courses,videos,docs,nodes,esc,icon,fmt,button,courseCard,videoRow,heading,empty,progress:()=>progress,learningBlock:(c,f)=>learning?.courseBlock(c,f)||'',refreshLibrary:group=>{history.replaceState(null,'','#library?group='+group);refresh();}});progress=readState(new Set(nodes.map(n=>n.id)));learning=await createLearning({index:libraryView.index,courses,byId,esc,icon,fmt,button,heading,empty,toast,progress:()=>progress,persist,playerOpen:()=>$('#player').open,closePlayer,snapshot:()=>({app:'TOEIC Studio',exportedAt:new Date().toISOString(),...progress,learning:learning.exportData()}),restore:value=>{bankFocus();progress=safeProgress(value,new Set(nodes.map(n=>n.id)));learning.importData(value.learning);persist();refresh()},refresh});navigate();if(!storageOK)toast('Chế độ lưu bị hạn chế. Bạn có thể xuất tiến độ để giữ lại dữ liệu.')}catch(error){$('#main').innerHTML=empty('Chưa mở được thư viện','Kiểm tra kết nối rồi tải lại trang. Bạn vẫn có thể mở thư mục Google Drive gốc.','folder',`<a href="${ROOT_URL}" target="_blank" rel="noopener noreferrer" class="btn btn-primary">Mở Google Drive</a>`);console.error(error)}}
boot();
